package com.google.javascript.jscomp;

import com.google.common.base.Preconditions;
import com.google.javascript.jscomp.CheckLevel;
import com.google.javascript.jscomp.Scope.Var;
import com.google.javascript.jscomp.testing.CompilerTestCase;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import com.google.javascript.rhino.jstype.EnumType;
import com.google.javascript.rhino.jstype.FunctionType;
import com.google.javascript.rhino.jstype.JSType;
import com.google.javascript.rhino.jstype.JSTypeNative;
import com.google.javascript.rhino.jstype.JSTypeRegistry;
import com.google.javascript.rhino.jstype.ObjectType;
import com.google.javascript.rhino.jstype.TernaryValue;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Set;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static com.google.javascript.jscomp.testing.BaseTestUtils.createCompiler;
import static org.junit.Assert.*;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyBoolean;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class TypeCheck_shouldTraverse_TriageGen0Test extends CompilerTestCase {

  private Compiler compiler;
  private JSTypeRegistry typeRegistry;
  private TypeCheck typeCheck;

  @Mock private NodeTraversal mockTraversal;
  @Mock private Node mockNode;
  @Mock private Node mockParent;
  @Mock private Scope mockScope;

  @Before
  public void setUp() {
    super.setUp();
    MockitoAnnotations.initMocks(this);
    compiler = createCompiler();
    typeRegistry = new JSTypeRegistry();
    typeRegistry.setGlobalScope(mockScope);

    // We use the constructor provided in the prompt. 
    // Since we cannot easily mock the internal 'report' or 'checkNoTypeCheckSection' 
    // without a full integration, we assume this test class is part of the jscomp suite.
    typeCheck = new TypeCheck(
        compiler, 
        null, 
        typeRegistry, 
        CheckLevel.OFF, 
        CheckLevel.OFF);
  }

  @Test
  public void testShouldTraverse_NotFunctionType() {
    when(mockNode.getType()).thenReturn(Token.VAR);
    when(mockTraversal.getScope()).thenReturn(mockScope);

    boolean result = typeCheck.shouldTraverse(mockTraversal, mockNode, mockParent);

    assertTrue(result);
  }

  @Test
  public void testShouldTraverse_FunctionType_NoConflict() {
    when(mockNode.getType()).thenReturn(Token.FUNCTION);
    when(mockTraversal.getScope()).thenReturn(mockScope);

    // Mocking JSType as FunctionType
    FunctionType functionType = new FunctionType(null, null, null, null, null);
    when(mockNode.getJSType()).thenReturn(functionType);

    // Mocking the name: function myFunc() {} -> first child is "myFunc"
    Node nameNode = mock(Node.class);
    when(nameNode.getString()).thenReturn("myFunc");
    when(mockNode.getFirstChild()).thenReturn(nameNode);

    // Case: Name is not in scope
    when(mockScope.isDeclared("myFunc", false)).thenReturn(false);

    boolean result = typeCheck.shouldTraverse(mockTraversal, mockNode, mockParent);

    assertTrue(result);
  }

  @Test
  public void testShouldTraverse_FunctionType_NameInScopeButIsFunctionType() {
    when(mockNode.getType()).thenReturn(Token.FUNCTION);
    when(mockTraversal.getScope()).thenReturn(mockScope);

    FunctionType functionType = new FunctionType(null, null, null, null, null);
    when(mockNode.getJSType()).thenReturn(functionType);

    Node nameNode = mock(Node.class);
    when(nameNode.getString()).thenReturn("myFunc");
    when(mockNode.getFirstChild()).thenReturn(nameNode);

    // Case: Name is in scope, but the existing variable is already a FunctionType
    when(mockScope.isDeclared("myFunc", false)).thenReturn(true);

    Node existingVar = mock(Node.class);
    when(existingVar.getType()).thenReturn(functionType);
    when(mockScope.getVar("myFunc")).thenReturn(existingVar);

    boolean result = typeCheck.shouldTraverse(mockTraversal, mockNode, mockParent);

    assertTrue(result);
  }

  @Test
  public void testShouldTraverse_FunctionType_EmptyName() {
    when(mockNode.getType()).thenReturn(Token.FUNCTION);
    when(mockTraversal.getScope()).thenReturn(mockScope);

    Node nameNode = mock(Node.class);
    when(nameNode.getString()).thenReturn("");
    when(mockNode.getFirstChild()).thenReturn(nameNode);

    boolean result = typeCheck.shouldTraverse(mockTraversal, mockNode, mockParent);

    assertTrue(result);
  }

  @Test
  public void testShouldTraverse_FunctionType_NullName() {
    when(mockNode.getType()).thenReturn(Token.FUNCTION);
    when(mockTraversal.getScope()).thenReturn(mockScope);

    Node nameNode = mock(Node.class);
    when(nameNode.getString()).thenReturn(null);
    when(mockNode.getFirstChild()).thenReturn(nameNode);

    boolean result = typeCheck.shouldTraverse(mockTraversal, mockNode, mockParent);

    assertTrue(result);
  }

  @Test
  public void testShouldTraverse_FunctionType_MasksVariable() {
    // This test targets the 'report' branch
    when(mockNode.getType()).thenReturn(Token.FUNCTION);
    when(mockTraversal.getScope()).thenReturn(mockScope);

    FunctionType functionType = new FunctionType(null, null, null, null, null);
    when(mockNode.getJSType()).thenReturn(functionType);

    Node nameNode = mock(Node.class);
    when(nameNode.getString()).thenReturn("myFunc");
    when(mockNode.getFirstChild()).thenReturn(nameNode);

    // Name is in scope
    when(mockScope.isDeclared("myFunc", false)).thenReturn(true);

    // Existing variable is NOT a function type (e.g., it's a String)
    Node existingVar = mock(Node.class);
    when(existingVar.getType()).thenReturn(new StringType());
    when(mockScope.getVar("myFunc")).thenReturn(existingVar);

    // Note: In a real environment, 'report' would trigger a warning. 
    // Since we are testing the logic flow, we ensure the execution reaches the end.
    boolean result = typeCheck.shouldTraverse(mockTraversal, mockNode, mockParent);

    assertTrue(result);
  }
}
